import pandas as pd

def clean(df):
    df = df.drop_duplicates(keep='first')
    df['Category'] = df['Category'].apply(lambda x: 'Office Supplies' if x.strip().lower() == 'office supplies' else x)
    return df

def answer(df):
    category_counts = df.groupby('Category')['Order_ID'].count()
    unique = df['Category'].unique()
    if len(unique) == 1:
        return {'all': len(df)}
    else:
        return category_counts.to_dict()
